CREATE TABLE users(id BIGSERIAL PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('ADMIN','MANAGER','EMPLOYEE')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE auth_tokens(id BIGSERIAL PRIMARY KEY,token_hash VARCHAR(64) NOT NULL UNIQUE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX auth_tokens_user_idx ON auth_tokens(user_id);
CREATE TABLE employee_profiles(id BIGSERIAL PRIMARY KEY,employee_number VARCHAR(30) NOT NULL UNIQUE,user_id BIGINT NOT NULL UNIQUE REFERENCES users(id),manager_id BIGINT REFERENCES users(id),department VARCHAR(120) NOT NULL,annual_balance INTEGER NOT NULL CHECK(annual_balance>=0),sick_balance INTEGER NOT NULL CHECK(sick_balance>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX employees_manager_idx ON employee_profiles(manager_id);CREATE INDEX employees_department_idx ON employee_profiles(department);
CREATE TABLE leave_requests(id BIGSERIAL PRIMARY KEY,employee_id BIGINT NOT NULL REFERENCES employee_profiles(id),type VARCHAR(20) NOT NULL CHECK(type IN('ANNUAL','SICK','UNPAID')),start_date DATE NOT NULL,end_date DATE NOT NULL,total_days INTEGER NOT NULL CHECK(total_days BETWEEN 1 AND 30),reason VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN('PENDING','APPROVED','REJECTED','CANCELLED')),reviewed_by BIGINT REFERENCES users(id),review_note VARCHAR(500),decided_at TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(end_date>=start_date));
CREATE INDEX leave_employee_dates_idx ON leave_requests(employee_id,start_date,end_date);CREATE INDEX leave_status_idx ON leave_requests(status);

